package com.example

import com.example.ExamQuestionHelper.QSpec

internal object BuddhismG11LiveExamSriLankaBank2 {
  private const val T = "ශ්‍රී ලංකාවේ බුදුසසුනේ ඉතිහාසය හා පුනර්ජීවනය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "ශ්‍රී ලංකාවේ බුදුසසුනේ ඉතිහාසය හා පුනර්ජීවනය අදාළ කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("ශ්‍රී ලංකාවේ බුදුදහම පිහිටුවීමෙන් පසු මෙරටට ලැබුණු ප්‍රධානම බෞද්ධ සංකේතය කුමක්ද?", "ජය ශ්‍රී මහා බෝධිය සහ දළදා වහන්සේ", "රන් තලිය", "සිංහ ආසනය", "ගල් පිළිම", "ජය ශ්‍රී මහා බෝධිය හා දළදා වහන්සේ උතුම් සංකේත වේ."),
    q("මිහිඳු හිමියන් මිහින්තලේදී දේවානම්පියතිස්ස රජුට ප්‍රථමයෙන් දේශනා කළ සූත්‍රය කුමක්ද?", "චූළහත්ථිපදෝපම සූත්‍රය", "මංගල සූත්‍රය", "රතන සූත්‍රය", "ධම්මචක්ක සූත්‍රය", "මිහිඳු හිමි චූළහත්ථිපදෝපම සූත්‍රය දෙසූහ."),
    q("දේවානම්පියතිස්ස රජුගේ මූලිකත්වයෙන් ඉදි වූ ලංකාවේ ප්‍රථම විහාරය පිහිටියේ කොහිද?", "අනුරාධපුර මහමෙවුනා උයනේ (මහාවිහාරය)", "මිහින්තලේ", "කැලණියේ", "මහියංගණයේ", "මහමෙවුනා උයන මහාවිහාරය විය."),
    q("සංඝමිත්තා තෙරණිය ශ්‍රී මහා බෝධි ශාඛාව වැඩම කරවා ගොඩබැස්ස වූ ස්ථානය කුමක්ද?", "ජම්부කෝළ වරාය (දඹකොළ පටුන)", "කොළඹ වරාය", "ගාලු වරාය", "මහතිත්ත වරාය", "දඹකොළ පටුනෙන් ගොඩබැස්සාය."),
    q("අනුරාධපුර යුගයේ ඉදි වූ ලංකාවේ ප්‍රථම චෛත්‍යය කුමක්ද?", "ථූපාරාමය", "රුවන්වැලි මහ සෑය", "මිරිසවැටිය", "අභයගිරිය", "ථූපාරාමය ලංකාවේ ප්‍රථම දාගැබයි."),
    q("ථූපාරාම චෛත්‍යයේ තැන්පත් කර ඇති බුදුරදුන්ගේ ශ්‍රී ධාතුව කුමක්ද?", "දකුණු අකුධාතුව", "නළා ධාතුව", "වාම දළදා වහන්සේ", "පත්‍ර ධාතුව", "දකුණු අකුධාතුව ථූපාරාමයේ ඇත."),
    q("දුටුගැමුණු රජතුමා විසින් කරවන ලද මහා ස්වර්ණමාලි මහා සෑය (රුවන්වැලි සෑය) ඉදි කිරීමේ ප්‍රධාන අරමුණ කුමක්ද?", "බුද්ධ ශාසනයේ චිරස්ථිතිය හා ධාතු නිධානය", "ධන රැස් කිරීම", "යුද්ධයක් කිරීම", "මළගිය අය සිහි කිරීම", "ශාසනයේ චිරස්ථිතිය උදෙසා ඉදි කළහ."),
    q("පොළොන්නරු යුගයේදී පළමු කතිකාවත පිහිටුවීමට මූලික වූ රජු හා තෙරුන් කවුද?", "මහා පරාක්‍රමබාහු රජු හා දිඹුලාගල මහා කාශ්‍යප හිමි", "අශෝක රජු හා මිහිඳු හිමි", "වළගම්බා රජු හා තිස්ස හිමි", "දුටුගැමුණු රජු හා ඉන්ද්‍රගුප්ත හිමි", "මහා පරාක්‍රමබාහු රජු කතිකාවත කළේය."),
    q("කෝට්ටේ යුගයේ බිහි වූ විශිෂ්ට කාව්‍යයක් වන 'කාව්‍යශේඛරය' රචනා කළේ කවුද?", "තොටගමුවේ ශ්‍රී රාහුල හිමි", "වීදාගම මෛත්‍රෙය හිමි", "ධර්මසේන හිමි", "බුද්ධඝෝෂ හිමි", "ශ්‍රී රාහුල හිමි කාව්‍යශේඛරය රචනා කළහ."),
    q("මහනුවර යුගයේදී උපසම්පදාව යළි පිහිටුවීමට සියම් රටින් භික්ෂූන් වහන්සේලා වැඩම කරවූ මහා තෙරුන් කවුද?", "වැලිවිට සරණංකර සංඝරාජ මහා තෙරුන් වහන්සේ", "රේවත හිමි", "සුමංගල හිමි", "ධර්මාලෝක හිමි", "වැලිවිට සරණංකර හිමියන් මූලික වූහ."),
    q("ඉංග්‍රීසි පාලන සමයේ ක්‍රිස්තියානි ආගමිකයන් සමඟ පැවති වාද අතරින් ප්‍රකටම 'පානදුරා වාදය' පැවැත්වුණු වර්ෂය කුමක්ද?", "1873 වර්ෂයේදී", "1865 දී", "1880 දී", "1890 දී", "1873 දී පානදුරා වාදය පැවැත්විණි."),
    q("පානදුරා වාදය පත්‍රිකා මගින් කියවා පැහැදී ලංකාවට පැමිණි ඇමරිකානු ජාතික පරම විඥානාර්ථවාදියා කවුද?", "කර්නල් හෙන්රි ස්ටීල් ඕල්කට්තුමා", "ඇනි බෙසන්ට්තුමිය", "ජේ.ආර්. ජයවර්ධන", "ඩී.එස්. සේනානායක", "ඕල්කට්තුමා ලංකාවට පැමිණියහ."),
    q("ලංකාවේ බෞද්ධ පාසල් ආරම්භ කරමින් අධ්‍යාපන නැංවීමට මූලික වූ සංවිධානය කුමක්ද?", "බෞද්ධ පරමවිඥානාර්ථ සංගමය", "මහාබෝධි සංගමය", "විද්‍යෝදය සභාව", "විද්‍යාලංකාර සභාව", "පරමවිඥානාර්ථ සංගමය පාසල් පිහිටුවීය."),
    q("අනගාරික ධර්මපාලතුමා ඉන්දියාවේ බුද්ධගයාව බෞද්ධයන්ට ලබා ගැනීමට පිහිටුවූ සංගමය කුමක්ද?", "මහාබෝධි සංගමය (1891 දී)", "බෞද්ධ කොංග්‍රසය", "විද්‍යෝදය සංගමය", "ශ්‍රී ලංකා සංගමය", "මහාබෝධි සංගමය පිහිටුවීය."),
    q("ලංකාවේ ප්‍රථම පිරිවෙන් ලෙස විද්‍යෝදය හා විද්‍යාලංකාර පිරිවෙන් ආරම්භ කළ නාහිමිවරුන් කවුද?", "හික්කඩුවේ සුමංගල නාහිමි සහ රත්මලානේ ශ්‍රී ධර්මාලෝක නාහිමි", "වැලිවිට සරණංකර හිමි", "තොටගමුවේ රාහුල හිමි", "බුද්ධඝෝෂ හිමි", "සුමංගල හිමි ඇතුළු පිරිස පිරිවෙන් ඇරඹූහ.")
  )
}
